import Foundation
import Vapor
import Crypto

// MARK: - Models
struct User {
    let id: UUID
    let username: String
    let role: Role
}

enum Role: String, Codable {
    case admin
    case editor
    case viewer
}

struct WebhookRequest: Content {
    let targetUrl: String
    let payload: String
    let callbackId: String
}

struct ProxyRequest: Content {
    let serviceEndpoint: String
    let method: String
    let headers: [String: String]?
}

// MARK: - URL Validation
class URLValidator {
    private static let blockedNetworks: [String] = [
        "169.254.",  // link-local
        "10.",       // private class A
        "192.168.",  // private class C
    ]

    private static let blockedHosts: Set<String> = [
        "localhost",
        "metadata.google.internal",
        "metadata.aws.internal"
    ]

    static func isAllowed(_ urlString: String) -> Bool {
        guard let url = URL(string: urlString),
              let host = url.host,
              let scheme = url.scheme else {
            return false
        }

        guard scheme == "https" || scheme == "http" else {
            return false
        }

        if blockedHosts.contains(host.lowercased()) {
            return false
        }

        // Resolve DNS to check for private IPs
        if let resolved = resolveHost(host) {
            for network in blockedNetworks {
                if resolved.hasPrefix(network) {
                    return false
                }
            }
            // Block 172.16.0.0/12
            if resolved.hasPrefix("172.") {
                let parts = resolved.split(separator: ".")
                if parts.count >= 2, let second = Int(parts[1]) {
                    if second >= 16 && second <= 31 {
                        return false
                    }
                }
            }
            if resolved == "127.0.0.1" || resolved == "0.0.0.0" {
                return false
            }
        }

        return true
    }

    static func resolveHost(_ host: String) -> String? {
        var hints = addrinfo()
        hints.ai_family = AF_INET
        hints.ai_socktype = SOCK_STREAM
        var result: UnsafeMutablePointer<addrinfo>?
        let status = getaddrinfo(host, nil, &hints, &result)
        guard status == 0, let addrInfo = result else { return nil }
        defer { freeaddrinfo(result) }
        let addr = addrInfo.pointee.ai_addr.withMemoryRebound(to: sockaddr_in.self, capacity: 1) { $0.pointee }
        return String(cString: inet_ntoa(addr.sin_addr))
    }
}

// MARK: - Access Control Middleware
class AccessControl {
    static func authorize(user: User, requiredRole: Role) -> Bool {
        let hierarchy: [Role: Int] = [.viewer: 1, .editor: 2, .admin: 3]
        guard let userLevel = hierarchy[user.role],
              let requiredLevel = hierarchy[requiredRole] else {
            return false
        }
        return userLevel >= requiredLevel
    }
}

// MARK: - Service Registry (internal service discovery)
class ServiceRegistry {
    private static let allowedServices: Set<String> = [
        "auth-service",
        "billing-service",
        "notification-service"
    ]

    private static var services: [String: String] = [
        "auth-service": "http://10.0.1.5:8080",
        "billing-service": "http://10.0.1.10:8080",
        "notification-service": "http://10.0.1.15:8080"
    ]

    static func resolve(_ serviceName: String) -> String? {
        guard allowedServices.contains(serviceName) else {
            return nil
        }
        return services[serviceName]
    }
}

// MARK: - Routes
func configureRoutes(_ app: Application) throws {

    // Public webhook endpoint - validates URLs strictly
    app.post("webhook") { req -> EventLoopFuture<Response> in
        let user = try authenticateUser(req)
        guard AccessControl.authorize(user: user, requiredRole: .editor) else {
            throw Abort(.forbidden)
        }

        let webhookReq = try req.content.decode(WebhookRequest.self)

        guard URLValidator.isAllowed(webhookReq.targetUrl) else {
            throw Abort(.badRequest, reason: "URL not allowed")
        }

        return req.client.post(URI(string: webhookReq.targetUrl)) { clientReq in
            try clientReq.content.encode(["payload": webhookReq.payload, "id": webhookReq.callbackId])
        }.map { response in
            return Response(status: .ok, body: .init(string: "Webhook delivered"))
        }
    }

    // Internal service proxy - admin only, restricted to known services
    app.post("internal", "proxy") { req -> EventLoopFuture<Response> in
        let user = try authenticateUser(req)
        guard AccessControl.authorize(user: user, requiredRole: .admin) else {
            throw Abort(.forbidden)
        }

        let proxyReq = try req.content.decode(ProxyRequest.self)
        let endpoint = buildEndpoint(from: proxyReq)

        guard !endpoint.isEmpty else {
            throw Abort(.badRequest, reason: "Invalid service endpoint")
        }

        return req.client.get(URI(string: endpoint)).map { response in
            return Response(status: response.status, body: response.body ?? .init())
        }
    }
}

// MARK: - Helpers
func buildEndpoint(from proxyReq: ProxyRequest) -> String {
    // Only allow service-name based routing, never raw URLs
    // Format must be: "service-name" or "service-name/path"
    let sanitized = proxyReq.serviceEndpoint
        .replacingOccurrences(of: "..", with: "")
        .replacingOccurrences(of: "://", with: "")

    // Reject if it contains a scheme (raw URL attempt)
    if proxyReq.serviceEndpoint.contains("://") {
        return ""
    }

    let components = sanitized.split(separator: "/", maxSplits: 1)
    guard !components.isEmpty else { return "" }

    let serviceName = String(components[0])
    let path = components.count > 1 ? String(components[1]) : ""

    // Only resolve from the allowlist-based registry
    guard let baseUrl = ServiceRegistry.resolve(serviceName) else {
        return ""
    }

    // Validate path doesn't contain suspicious patterns
    let forbiddenPatterns = ["@", "\\", "%00", "\r", "\n"]
    for pattern in forbiddenPatterns {
        if path.contains(pattern) {
            return ""
        }
    }

    return "\(baseUrl)/\(path)"
}

func authenticateUser(_ req: Request) throws -> User {
    guard let token = req.headers.bearerAuthorization?.token else {
        throw Abort(.unauthorized)
    }
    // In production, verify JWT and extract claims
    return try verifyToken(token)
}

// Secret used to authenticate/verify token signatures. In production this
// MUST be loaded from a secure secret store / environment, never hardcoded.
private let tokenSigningKey: SymmetricKey = {
    guard let raw = Environment.get("TOKEN_SIGNING_KEY"), !raw.isEmpty else {
        fatalError("TOKEN_SIGNING_KEY environment variable must be set")
    }
    return SymmetricKey(data: Data(raw.utf8))
}()

func verifyToken(_ token: String) throws -> User {
    // Token format: base64(payload).base64(hmac-sha256(payload))
    // The signature is verified BEFORE any claim (including role) is trusted.
    let parts = token.split(separator: ".", maxSplits: 1)
    guard parts.count == 2,
          let payloadData = Data(base64Encoded: String(parts[0])),
          let providedSig = Data(base64Encoded: String(parts[1])) else {
        throw Abort(.unauthorized)
    }

    // Recompute the expected HMAC over the raw payload bytes.
    let expectedSig = Data(HMAC<SHA256>.authenticationCode(for: payloadData, using: tokenSigningKey))

    // Constant-time comparison to avoid timing side channels.
    guard expectedSig.count == providedSig.count else {
        throw Abort(.unauthorized)
    }
    var mismatch: UInt8 = 0
    for (a, b) in zip(expectedSig, providedSig) {
        mismatch |= a ^ b
    }
    guard mismatch == 0 else {
        throw Abort(.unauthorized)
    }

    guard let claims = try? JSONDecoder().decode(TokenClaims.self, from: payloadData) else {
        throw Abort(.unauthorized)
    }
    return User(id: claims.sub, username: claims.username, role: claims.role)
}

struct TokenClaims: Codable {
    let sub: UUID
    let username: String
    let role: Role
}
